package net.civeira.phylax.features.notification.message.infrastructure.driver.rest;

import java.util.List;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.ws.rs.core.Response;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.generated.openapi.api.MessageBatchApi;

@RequiredArgsConstructor
@ApplicationScoped
public class MessageBatchController implements MessageBatchApi {

  /**
   * Message
   *
   * @autogenerated BatchControllerGenerator
   */
  private final MessageDeleteController deleteController;

  /**
   * @autogenerated BatchControllerGenerator
   * @param uids
   * @param search
   * @param tenant
   * @param tenants
   * @return
   */
  @Override
  public Response messageApiBatchDelete(final List<String> uids, final String search,
      final String tenant, final List<String> tenants) {
    return deleteController.messageApiBatchDelete(uids, search, tenant, tenants);
  }

  /**
   * @autogenerated BatchControllerGenerator
   * @param batchId
   * @return
   */
  @Override
  public Response messageApiBatchDeleteQuery(final String batchId) {
    return deleteController.messageApiBatchDeleteQuery(batchId);
  }
}
